"""Generate ``docs/rules.md`` from rule metadata.

Run as ``python -m roschema.rules.gendocs`` (from the repo root) to regenerate
the rule reference. A test asserts the committed file stays in sync.
"""

from __future__ import annotations

import sys
from pathlib import Path

from .breaking import ALL_BREAKING_RULES
from .lint import ALL_LINT_RULES
from .model import LintRule, Rule

_HEADER = (
    "# Rule reference\n\n"
    "Generated by `python -m roschema.rules.gendocs`; do not edit by hand.\n"
)


def render_docs() -> str:
    """Render the full rule reference as Markdown."""
    parts = [_HEADER, "\n## Breaking-change rules (`check`)\n"]
    for rule in ALL_BREAKING_RULES:
        parts.append(_render_breaking(rule))
    parts.append("\n## Lint rules (`lint`)\n")
    for lint_rule in ALL_LINT_RULES:
        parts.append(_render_lint(lint_rule))
    return "\n".join(parts).rstrip("\n") + "\n"


def _render_breaking(rule: Rule) -> str:
    lines = [
        f"### {rule.id} -- {rule.title}",
        "",
        rule.description,
        "",
        f"- Levels: {', '.join(rule.levels) or 'n/a'}",
        f"- Default severity: {rule.default_severity.value}",
        "",
        f"*Rationale:* {rule.rationale}",
    ]
    if rule.example_before or rule.example_after:
        lines += [
            "",
            "```",
            f"# before\n{rule.example_before}",
            "# after",
            rule.example_after,
            "```",
        ]
    return "\n".join(lines) + "\n"


def _render_lint(rule: LintRule) -> str:
    return (
        "\n".join(
            [
                f"### {rule.id} -- {rule.title}",
                "",
                rule.description,
                "",
                f"- Default severity: {rule.default_severity.value}",
                "",
                f"*Rationale:* {rule.rationale}",
            ]
        )
        + "\n"
    )


_DOCS_PATH = Path("docs/rules.md")


def main(argv: list[str] | None = None) -> int:
    """CLI: no args writes the docs; ``--check`` verifies they are in sync."""
    argv = sys.argv[1:] if argv is None else argv
    rendered = render_docs()
    if not argv:
        _DOCS_PATH.parent.mkdir(parents=True, exist_ok=True)
        _DOCS_PATH.write_text(rendered, encoding="utf-8")
        print(f"wrote {_DOCS_PATH}")
        return 0
    if argv == ["--check"]:
        if _DOCS_PATH.is_file() and _DOCS_PATH.read_text(encoding="utf-8") == rendered:
            return 0
        print(
            "docs/rules.md is stale; regenerate with `python -m roschema.rules.gendocs`",
            file=sys.stderr,
        )
        return 1
    print("usage: python -m roschema.rules.gendocs [--check]", file=sys.stderr)
    return 2


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())
